<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue';
import {api} from '../api';
import {BOOK_LABELS,type WordBook,type LearningBooks} from '../../../shared/learning';
const props=defineProps<{initialBook?:WordBook}>();const emit=defineEmits<{open:[id:number];start:[]}>();
const book=ref<WordBook>(props.initialBook??'unfamiliar'),page=ref(1),data=ref<LearningBooks|null>(null),busy=ref(false),failed=ref(false);let alive=true,version=0;
const books:WordBook[]=['mastered','familiar','unfamiliar','new'];
async function load(){const n=++version;busy.value=true;failed.value=false;try{const result=await api<LearningBooks>(`/api/learning/books?book=${book.value}&page=${page.value}`);if(alive&&n===version)data.value=result;}catch{if(alive&&n===version)failed.value=true;}finally{if(alive&&n===version)busy.value=false;}}
function select(value:WordBook){if(value===book.value)return;book.value=value;page.value=1;data.value=null;load();}
function changePage(delta:number){page.value+=delta;load();}
watch(()=>props.initialBook,value=>{if(value)select(value);});onMounted(load);onUnmounted(()=>{alive=false;version++;});
</script>
<template><main class="page word-books"><div class="books-heading"><h1>我的单词本</h1><button class="btn primary" @click="emit('start')">开始背单词</button></div><nav class="book-tabs" aria-label="单词本"><button v-for="b in books" :key="b" type="button" :aria-pressed="book===b" @click="select(b)">{{ BOOK_LABELS[b] }} <span v-if="data">{{ data.counts[b] }}</span></button></nav>
 <p v-if="failed" class="note" role="status">单词本未能载入。<button class="link" @click="load">重试</button></p><p v-else-if="busy" class="note">正在载入…</p>
 <template v-if="data&&!busy&&!failed"><p class="small muted">共 {{ data.total }} 个词 · 根据测试表现自动调整</p><div v-if="data.items.length" class="book-list"><button v-for="word in data.items" :key="word.id" class="book-word" @click="emit('open',word.id)"><span class="book-headword">{{ word.headword }}<small>{{ word.phonetic }}</small></span><span class="book-meaning">{{ word.meaning.split('\n')[0] }}</span><span class="tag" :class="{core:word.level==='三级'}">{{ word.level==='三级'?'核心词':'二级词' }}</span></button></div><section v-else class="panel"><p>这个单词本还没有单词。</p></section><div v-if="data.total>data.size" class="book-pagination"><button class="btn" :disabled="page<=1" @click="changePage(-1)">上一页</button><span>{{ page }} / {{ Math.ceil(data.total/data.size) }}</span><button class="btn" :disabled="page*data.size>=data.total" @click="changePage(1)">下一页</button></div></template></main></template>
<style scoped>
.books-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;}.books-heading h1{font-size:25px;}.book-tabs{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0 20px;}.book-tabs button{min-height:44px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--ink-2);padding:9px 16px;}.book-tabs button[aria-pressed=true]{background:var(--primary);color:var(--surface);border-color:var(--primary);}.book-tabs span{margin-left:8px;}.book-list{border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--surface);}.book-word{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.5fr) auto;align-items:center;gap:20px;width:100%;min-height:80px;padding:16px 20px;background:var(--surface);color:var(--ink);border:0;border-bottom:1px solid var(--line);text-align:left;}.book-word:last-child{border-bottom:0;}.book-headword{font:24px/1.3 var(--font-word);overflow-wrap:anywhere;}.book-headword small{display:block;font:12px/1.5 var(--font-ui);color:var(--ink-2);margin-top:5px;}.book-meaning{font-size:14px;overflow-wrap:anywhere;}.book-pagination{display:flex;justify-content:center;align-items:center;gap:16px;margin-top:22px;}@media(max-width:640px){.book-word{grid-template-columns:minmax(0,1fr) auto;gap:10px;}.book-meaning{grid-row:2;grid-column:1/-1;}.book-tabs button{padding:8px 11px;}.books-heading h1{font-size:22px;}.books-heading .btn{padding:10px 12px;}}
</style>
